package com.backend.nutri_predic.consumo.controller; import com.backend.nutri_predic.common.service.AccessService; import com.backend.nutri_predic.consumo.dto.SeguimientoPcsResponse; import com.backend.nutri_predic.consumo.service.SeguimientoPcsService; import java.time.LocalDate; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/clientes/{clienteId}/pcs/evolucion") public class SeguimientoPcsController {private final AccessService access;private final SeguimientoPcsService service;public SeguimientoPcsController(AccessService a,SeguimientoPcsService s){access=a;service=s;}@GetMapping public SeguimientoPcsResponse obtener(@PathVariable Long clienteId,@RequestParam LocalDate fechaCorte,Authentication a){access.client(clienteId,a);return service.evolucion(clienteId,fechaCorte);}}
